do $test$
declare initial jsonb; edited jsonb; reloaded jsonb; row_index int;
begin
 initial:=public.gevyro_load_workspace()->'workspace';
 select (i-1)::int into row_index from jsonb_array_elements(initial->'obligations') with ordinality x(doc,i) where doc->>'id'='purchase:4';
 if initial->'obligations'->row_index->>'date'<>'2026-11-05' then raise exception 'FAIL initial November date'; end if;
 edited:=jsonb_set(initial,array['obligations',row_index::text,'date'],'"2026-12-05"');
 edited:=jsonb_set(edited,array['obligations',row_index::text,'originalDate'],'"2026-11-05"');
 edited:=jsonb_set(edited,array['obligations',row_index::text,'originalAmount'],initial->'obligations'->row_index->'amount');
 perform public.gevyro_save_workspace(edited,1);
 reloaded:=public.gevyro_load_workspace()->'workspace';
 if (select document->>'date' from gevyro_finance.obligations where user_id=auth.uid() and id='purchase:4')<>'2026-12-05' then raise exception 'FAIL individual document not saved'; end if;
 if (select due_date from gevyro_finance.obligations where user_id=auth.uid() and id='purchase:4')<>date '2026-12-05' then raise exception 'FAIL indexed due date not saved'; end if;
 if (select count(*) from gevyro_finance.obligations where user_id=auth.uid() and due_date>=date '2026-11-01' and due_date<date '2026-12-01')<>0 then raise exception 'FAIL obsolete November membership'; end if;
 if (select count(*) from gevyro_finance.obligations where user_id=auth.uid() and due_date>=date '2026-12-01' and due_date<date '2027-01-01')<>2 then raise exception 'FAIL December membership'; end if;
 if reloaded->'payments'<>initial->'payments' or reloaded->'plans'<>initial->'plans' then raise exception 'FAIL payment or parent mutation'; end if;
 if (select jsonb_agg(doc order by doc->>'id') from jsonb_array_elements(reloaded->'obligations') doc where doc->>'id'<>'purchase:4') is distinct from (select jsonb_agg(doc order by doc->>'id') from jsonb_array_elements(initial->'obligations') doc where doc->>'id'<>'purchase:4') then raise exception 'FAIL other installment mutation'; end if;
 if (select sum((doc->>'amount')::bigint) from jsonb_array_elements(reloaded->'obligations') doc)<>204123 then raise exception 'FAIL amount changed'; end if;
 if (public.gevyro_load_workspace()->>'revision')::int<>2 then raise exception 'FAIL revision confirmation'; end if;
end $test$;
